package com.smarttask.controller;
import com.smarttask.dto.ApiDtos.*;import com.smarttask.entity.Task;import com.smarttask.repository.UserRepository;import com.smarttask.service.TaskService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController {private final TaskService service;private final UserRepository users;public TaskController(TaskService s,UserRepository u){service=s;users=u;}private Long uid(Authentication a){return users.findByEmail(a.getName()).orElseThrow().getId();}@GetMapping public List<TaskView> list(Authentication a,@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String sort){return service.list(uid(a),q,status,sort);}@PostMapping public TaskView create(Authentication a,@Valid @RequestBody TaskRequest r){return service.create(uid(a),r);}@PutMapping("/{id}") public TaskView update(Authentication a,@PathVariable Long id,@Valid @RequestBody TaskRequest r){return service.update(uid(a),id,r);}@PatchMapping("/{id}/status") public TaskView status(Authentication a,@PathVariable Long id,@RequestParam Task.Status value){return service.status(uid(a),id,value);}@DeleteMapping("/{id}") public void delete(Authentication a,@PathVariable Long id){service.delete(uid(a),id);}}
